import type { AuditReport, IssueStatus } from '../types/audit';

export const REPORT_FOOTER_DISCLAIMER =
  'Generated by Digital Automation Pulse. Scores are AI-estimated and should be validated with tools such as Google Search Console and PageSpeed Insights.';

export const TARGET_COUNTRIES = [
  'Global',
  'United States',
  'United Kingdom',
  'Canada',
  'Australia',
  'Germany',
  'France',
  'India',
  'Singapore',
  'Japan',
  'Brazil',
];

/**
 * Normalizes user input (e.g., "example.com" -> "https://example.com/")
 * and performs client-side validation before sending to the API.
 */
export function validateAndNormalizeUrl(raw: string): { valid: true; normalized: string } | { valid: false; error: string } {
  const trimmed = raw.trim();
  if (!trimmed) {
    return { valid: false, error: 'Enter a website URL (for example, example.com).' };
  }

  const candidate = /^https?:\/\//i.test(trimmed) ? trimmed : `https://${trimmed}`;

  try {
    const parsed = new URL(candidate);
    if (parsed.protocol !== 'http:' && parsed.protocol !== 'https:') {
      return { valid: false, error: 'Only HTTP and HTTPS website URLs are supported.' };
    }
    const host = parsed.hostname.toLowerCase();
    if (!host || !host.includes('.') || host === 'localhost' || host.endsWith('.local')) {
      return { valid: false, error: 'Enter a valid public domain name such as acme.com.' };
    }
    if (/^(127\.|10\.|192\.168\.|169\.254\.|0\.)/.test(host)) {
      return { valid: false, error: 'Local or private network IP addresses cannot be audited.' };
    }
    return { valid: true, normalized: parsed.toString() };
  } catch {
    return { valid: false, error: 'That does not look like a valid URL. Try example.com or https://example.com.' };
  }
}

export function extractDomain(url: string): string {
  try {
    return new URL(url).hostname.replace(/^www\./, '');
  } catch {
    return url;
  }
}

export function formatAuditDate(isoDate: string): string {
  try {
    return new Intl.DateTimeFormat('en-US', {
      month: 'short',
      day: 'numeric',
      year: 'numeric',
      hour: '2-digit',
      minute: '2-digit',
    }).format(new Date(isoDate));
  } catch {
    return isoDate;
  }
}

export function formatShortDate(isoDate: string): string {
  try {
    return new Intl.DateTimeFormat('en-US', {
      month: 'short',
      day: 'numeric',
      year: 'numeric',
    }).format(new Date(isoDate));
  } catch {
    return isoDate;
  }
}

export function getScoreGrade(score: number): 'A' | 'B' | 'C' | 'D' | 'F' {
  if (score >= 90) return 'A';
  if (score >= 80) return 'B';
  if (score >= 65) return 'C';
  if (score >= 50) return 'D';
  return 'F';
}

export function getScoreColorTokens(score: number): {
  stroke: string;
  text: string;
  badgeBg: string;
  label: string;
} {
  if (score >= 80) {
    return {
      stroke: '#16A34A',
      text: 'text-emerald-700 dark:text-emerald-400',
      badgeBg: 'bg-emerald-50 text-emerald-800 border-emerald-200 dark:bg-emerald-950/50 dark:text-emerald-300 dark:border-emerald-800',
      label: 'Strong',
    };
  }
  if (score >= 50) {
    return {
      stroke: '#D97706',
      text: 'text-amber-700 dark:text-amber-400',
      badgeBg: 'bg-amber-50 text-amber-800 border-amber-200 dark:bg-amber-950/50 dark:text-amber-300 dark:border-amber-800',
      label: 'Needs Work',
    };
  }
  return {
    stroke: '#DC2626',
    text: 'text-red-700 dark:text-red-400',
    badgeBg: 'bg-red-50 text-red-800 border-red-200 dark:bg-red-950/50 dark:text-red-300 dark:border-red-800',
    label: 'Critical',
  };
}

export function getStatusColorClasses(status: IssueStatus): string {
  switch (status) {
    case 'Critical':
      return 'bg-red-50 text-red-800 border-red-200 dark:bg-red-950/50 dark:text-red-300 dark:border-red-800';
    case 'Warning':
      return 'bg-amber-50 text-amber-800 border-amber-200 dark:bg-amber-950/50 dark:text-amber-300 dark:border-amber-800';
    case 'Pass':
      return 'bg-emerald-50 text-emerald-800 border-emerald-200 dark:bg-emerald-950/50 dark:text-emerald-300 dark:border-emerald-800';
    case 'Info':
    default:
      return 'bg-slate-100 text-slate-700 border-slate-200 dark:bg-slate-800 dark:text-slate-300 dark:border-slate-700';
  }
}

function escapeCsvCell(value: string): string {
  const safe = String(value ?? '').replace(/"/g, '""');
  return `"${safe}"`;
}

function toCsvRow(cells: string[]): string {
  return cells.map(escapeCsvCell).join(',');
}

export function downloadBlob(filename: string, content: string, mimeType: string) {
  const blob = new Blob([content], { type: mimeType });
  const url = URL.createObjectURL(blob);
  const anchor = document.createElement('a');
  anchor.href = url;
  anchor.download = filename;
  document.body.appendChild(anchor);
  anchor.click();
  document.body.removeChild(anchor);
  URL.revokeObjectURL(url);
}

export function exportIssuesCsv(report: AuditReport) {
  const rows: string[] = [
    toCsvRow(['Source', 'Category / Check', 'Severity', 'Effort', 'Finding / Detail', 'Recommendation / Fix', 'Why It Matters']),
  ];
  for (const item of report.seoAudit) {
    rows.push(
      toCsvRow([
        'SEO Audit',
        item.item,
        item.status,
        item.effort || 'Medium',
        item.finding,
        item.recommendation,
        item.whyItMatters || '',
      ])
    );
  }
  for (const tech of report.technicalChecklist) {
    rows.push(
      toCsvRow([
        `Technical (${tech.category})`,
        tech.check,
        tech.status,
        tech.effort || 'Medium',
        tech.detail,
        tech.fix,
        tech.whyItMatters || '',
      ])
    );
  }
  rows.push('');
  rows.push(toCsvRow([REPORT_FOOTER_DISCLAIMER]));
  const domain = extractDomain(report.url);
  downloadBlob(`dap-issues-${domain}.csv`, rows.join('\n'), 'text/csv;charset=utf-8;');
}

export function exportKeywordsCsv(report: AuditReport) {
  const rows: string[] = [
    toCsvRow(['Type', 'Keyword', 'Intent', 'Estimated Difficulty', 'Estimated Volume Tier', 'Opportunity']),
  ];
  for (const k of report.keywordSuggestions.primary) {
    rows.push(toCsvRow(['Primary (Estimated)', k.keyword, k.intent, k.estimatedDifficulty, k.estimatedVolumeTier, k.opportunity]));
  }
  for (const k of report.keywordSuggestions.longTail) {
    rows.push(toCsvRow(['Long-Tail (Estimated)', k.keyword, k.intent, k.estimatedDifficulty, k.estimatedVolumeTier, k.opportunity]));
  }
  for (const q of report.keywordSuggestions.questionKeywords) {
    rows.push(toCsvRow(['Question Keyword', q, 'Informational', 'Estimated', 'Estimated', 'AEO / FAQ targeting']));
  }
  for (const gap of report.keywordSuggestions.competitorGapKeywords) {
    rows.push(toCsvRow(['Competitor Gap', gap, 'Commercial/Informational', 'Estimated', 'Estimated', 'Competitor content gap']));
  }
  rows.push('');
  rows.push(toCsvRow([REPORT_FOOTER_DISCLAIMER]));
  const domain = extractDomain(report.url);
  downloadBlob(`dap-keywords-${domain}.csv`, rows.join('\n'), 'text/csv;charset=utf-8;');
}

export function exportTechnicalCsv(report: AuditReport) {
  const rows: string[] = [
    toCsvRow(['Category', 'Check', 'Status', 'Effort', 'Observed Detail', 'Recommended Fix', 'Why It Matters']),
  ];
  for (const t of report.technicalChecklist) {
    rows.push(toCsvRow([t.category, t.check, t.status, t.effort || 'Medium', t.detail, t.fix, t.whyItMatters || '']));
  }
  rows.push('');
  rows.push(toCsvRow([REPORT_FOOTER_DISCLAIMER]));
  const domain = extractDomain(report.url);
  downloadBlob(`dap-technical-${domain}.csv`, rows.join('\n'), 'text/csv;charset=utf-8;');
}

export function exportJsonReport(report: AuditReport) {
  const payload = {
    ...report,
    disclaimer: REPORT_FOOTER_DISCLAIMER,
  };
  const domain = extractDomain(report.url);
  downloadBlob(`dap-audit-${domain}.json`, JSON.stringify(payload, null, 2), 'application/json;charset=utf-8;');
}

export function buildPlainTextSummary(report: AuditReport): string {
  const grade = getScoreGrade(report.scores.overall);
  const topFixes = report.priorityFixes
    .slice(0, 5)
    .map((f, i) => `  ${i + 1}. [${f.impact} Impact / ${f.effort} Effort] ${f.title}: ${f.description}`)
    .join('\n');

  return [
    `DIGITAL AUTOMATION PULSE — MARKETING AUDIT SUMMARY`,
    `Website: ${report.url}`,
    `Market: ${report.targetCountry || 'Global'}`,
    `Audit Date: ${formatAuditDate(report.auditDate)}`,
    ``,
    `SCORES`,
    `  Overall Pulse Score: ${report.scores.overall}/100 (Grade ${grade})`,
    `  SEO: ${report.scores.seo}/100 | Content: ${report.scores.content}/100 | Keywords: ${report.scores.keywords}/100`,
    `  Technical: ${report.scores.technical}/100 | AI-Search Readiness: ${report.scores.aiSearch}/100`,
    ``,
    `EXECUTIVE SUMMARY`,
    report.executiveSummary,
    ``,
    `TOP PRIORITY FIXES`,
    topFixes,
    ``,
    `30-DAY QUICK ACTIONS`,
    ...report.roadmap.days30.map((d) => `  - ${d}`),
    ``,
    REPORT_FOOTER_DISCLAIMER,
  ].join('\n');
}
